node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import getNote from './tgcloud/endpoints/getNote.js';
const ctx = { initData: { user: { id: 123 } } };
assert.deepEqual(await getNote({}, ctx), { userId: 123 });
assert.deepEqual(await getNote({ userId: 999 }, ctx), { userId: 123 });
await assert.rejects(() => getNote({}, {}), TypeError);
